package com.universe.community.dto.response; import com.universe.community.entity.Comment; import lombok.AllArgsConstructor; import lombok.Getter; import java.time.LocalDateTime; @Getter @AllArgsConstructor public class CommentResponse { private Long commentId; private Long postId; private Long authorId; private String authorName; private String content; private boolean anonymous; private Long parentCommentId; private LocalDateTime createdAt; private LocalDateTime updatedAt; public static CommentResponse from(Comment c){return new CommentResponse(c.getId(),c.getPost().getId(),c.getUser().getId(),Boolean.TRUE.equals(c.getIsAnonymous())?"익명":c.getUser().getNickname(),c.getContent(),Boolean.TRUE.equals(c.getIsAnonymous()),c.getParentComment()==null?null:c.getParentComment().getId(),c.getCreatedAt(),c.getUpdatedAt());}}
